const payload = $json.body ?? $json;
const subVertical = `${payload.subVertical ?? 'other'}`.toLowerCase();
const text = `${payload.biggestLeak ?? ''} ${payload.afterHoursCoverage ?? ''} ${payload.currentTools ?? ''}`.toLowerCase();
const urgencyTermsBySubVertical = {
  plumbing: ['leak', 'flooding', 'no water', 'no-water', 'sewage', 'gas smell', 'water heater'],
  electrical: ['sparking', 'smoke', 'burning', 'no power', 'breaker tripping', 'panel'],
  'tree-service': ['tree on', 'power lines', 'blocking road', 'storm damage', 'leaning'],
  'pest-control': ['infestation', 'in the house', 'aggressive', 'allergic'],
  landscaping: ['recurring', 'design', 'install', 'cleanup'],
  'garage-doors': ['stuck', 'spring', 'opener', 'broken'],
  'fence-deck': ['damaged', 'install', 'repair'],
  'junk-removal': ['estate', 'cleanout', 'today', 'urgent'],
  painting: ['interior', 'exterior', 'cabinet'],
  'pressure-washing': ['driveway', 'house', 'deck'],
  other: []
};
const safetyTriggersBySubVertical = {
  plumbing: ['gas smell', 'sewage', 'flooding', 'active leak'],
  electrical: ['sparking', 'smoke', 'burning', 'fire'],
  'tree-service': ['power lines', 'tree on house', 'tree on power'],
  'pest-control': [],
  landscaping: [],
  'garage-doors': [],
  'fence-deck': [],
  'junk-removal': [],
  painting: [],
  'pressure-washing': [],
  other: []
};
const urgencyTerms = urgencyTermsBySubVertical[subVertical] ?? [];
const safetyTriggers = safetyTriggersBySubVertical[subVertical] ?? [];
const urgencyHits = urgencyTerms.filter((term) => text.includes(term)).length;
const safetyHits = safetyTriggers.filter((term) => text.includes(term)).length;
let priority;
if (safetyHits > 0) priority = 'safety-emergency';
else if (urgencyHits >= 2) priority = 'urgent-callback';
else if (urgencyHits === 1) priority = 'same-day';
else priority = 'standard';
const leadId = `DEMO-HOMESVC-${subVertical.toUpperCase()}-${Date.now()}`;
return [{ json: { leadId, subVertical, priority, urgencyHits, safetyHits, voiceAgent: `home-services-${subVertical}`, nextAction: priority === 'safety-emergency' ? 'Trigger voice-agent safety branch + internal SMS to dispatcher.' : priority === 'urgent-callback' ? 'Create dispatcher callback task now.' : 'Add to service queue.', lead: payload } }];
